const validateCardForCBT = `-- name: ValidateCardForCBT :many
SELECT p.id AS participant_id, p.session_id, p.student_id, es.title AS session_title, es.status AS session_status,
       es.scheduled_start, es.scheduled_end
FROM cbt_exam_participants p
JOIN cbt_exam_sessions es ON es.id = p.session_id
JOIN student_id_cards c ON c.student_id = p.student_id
WHERE c.token_hash = $1 AND c.status = 'active'
  AND es.status IN ('scheduled','active')
  AND es.scheduled_end >= NOW() - INTERVAL '2 hours'
ORDER BY es.scheduled_start ASC
`

type ValidateCardForCBTRow struct {
	ParticipantID  pgtype.UUID          `json:"participant_id"`
	SessionID      pgtype.UUID          `json:"session_id"`
	StudentID      pgtype.UUID          `json:"student_id"`
	SessionTitle   string               `json:"session_title"`
	SessionStatus  CbtSessionStatusEnum `json:"session_status"`
	ScheduledStart pgtype.Timestamptz   `json:"scheduled_start"`
	ScheduledEnd   pgtype.Timestamptz   `json:"scheduled_end"`
}

func (q *Queries) ValidateCardForCBT(ctx context.Context, tokenHash string) ([]ValidateCardForCBTRow, error) {
	rows, err := q.db.Query(ctx, validateCardForCBT, tokenHash)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ValidateCardForCBTRow{}
	for rows.Next() {
		var i ValidateCardForCBTRow
		if err := rows.Scan(
			&i.ParticipantID,
			&i.SessionID,
			&i.StudentID,
			&i.SessionTitle,
			&i.SessionStatus,
			&i.ScheduledStart,
			&i.ScheduledEnd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
